connections=[]
for i,(theme,refs,hint,explanation,distractors) in enumerate(THEMES):
    connections.append(dict(id=slug(theme),number=i+1,theme=theme,refs=refs.split(),hint=hint,explanation=explanation,distractors=distractors.split('|'),anchor=refs.split()[0].split('-')[0]))

