scenarios=[]
for i,row in enumerate(SCENARIOS):
    title,topic,ref,scene,prompt,options,follow,prompt2,options2,takeaway=row
    scenarios.append(dict(id=slug(title),number=i+1,title=title,topic=topic,ref=ref,scene=scene,prompt=prompt,options=[dict(text=t,consequence=c,constructive=j==0) for j,(t,c) in enumerate(options)],followup=follow,prompt2=prompt2,options2=[dict(text=t,consequence=c,constructive=j==0) for j,(t,c) in enumerate(options2)],takeaway=takeaway))

